def _parse_lines(text: str) -> dict[str, dict[str, str]]:
    """Read the sections and raw values, before interpolation."""
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    current_key: str | None = None

    for lineno, line in enumerate(text.splitlines(), 1):
        stripped = line.strip()
        if not stripped:
            current_key = None
            continue
        if stripped[0] in "#;":
            current_key = None
            continue

        if line[0].isspace() and current_key is not None:
            assert current_section is not None
            sections[current_section][current_key] += "\n" + stripped
            continue

        if stripped.startswith("[") and stripped.endswith("]"):
            name = stripped[1:-1].strip()
            sections.setdefault(name, {})
            current_section = name
            current_key = None
            continue

        equals = stripped.find("=")
        colon = stripped.find(":")
        if equals == -1:
            split_at = colon
        elif colon == -1:
            split_at = equals
        else:
            split_at = min(equals, colon)
        if split_at == -1:
            raise ParseError(lineno, "unrecognized line")
        if current_section is None:
            raise ParseError(lineno, "key before any section")

        key = stripped[:split_at].strip().lower()
        if not key:
            raise ParseError(lineno, "empty key")
        sections[current_section][key] = stripped[split_at + 1 :].strip()
        current_key = key

    return sections


def _resolve_reference(
    reference: str,
    current_section: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    stack: list[tuple[str, str]],
) -> str:
    if ":" in reference:
        section_name, key = reference.split(":", 1)
        section_name = section_name.strip()
        key = key.strip().lower()
        if section_name not in sections or key not in sections[section_name]:
            raise InterpolationError(
                f"missing reference {reference!r}"
            )
    else:
        section_name = current_section
        key = reference.strip().lower()
        if key not in sections[section_name]:
            raise InterpolationError(
                f"missing key {key!r} in section {section_name!r}"
            )

    return _resolve_value(section_name, key, sections, cache, stack)


def _interpolate_text(
    text: str,
    section_name: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    stack: list[tuple[str, str]],
) -> str:
    result: list[str] = []
    i = 0
    length = len(text)
    while i < length:
        character = text[i]
        if character != "$":
            result.append(character)
            i += 1
            continue
        if text.startswith("$$", i):
            result.append("$")
            i += 2
            continue
        if text.startswith("${", i):
            end = text.find("}", i + 2)
            if end != -1:
                reference = text[i + 2 : end]
                result.append(
                    _resolve_reference(reference, section_name, sections, cache, stack)
                )
                i = end + 1
                continue
        result.append("$")
        i += 1
    return "".join(result)


def _resolve_value(
    section_name: str,
    key: str,
    sections: dict[str, dict[str, str]],
    cache: dict[tuple[str, str], str],
    stack: list[tuple[str, str]],
) -> str:
    token = (section_name, key)
    if token in cache:
        return cache[token]

    for position, active in enumerate(stack):
        if active == token:
            cycle = stack[position:] + [token]
            path = " -> ".join(f"{section}:{name}" for section, name in cycle)
            raise InterpolationError(f"interpolation cycle: {path}")

    stack.append(token)
    try:
        value = _interpolate_text(
            sections[section_name][key], section_name, sections, cache, stack
        )
    finally:
        stack.pop()
    cache[token] = value
    return value


def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections = _parse_lines(text)

    cache: dict[tuple[str, str], str] = {}
    result: dict[str, dict[str, str]] = {}
    for section_name, values in sections.items():
        result[section_name] = {}
        for key in values:
            result[section_name][key] = _resolve_value(
                section_name, key, sections, cache, []
            )
    return result
